visits <- data.frame(
  date = seq(as.Date("2026-09-07"), by = "day", length.out = 28),
  visitors = c(112, 98, 105, 120, 134, 76, 41, 108, 95, -1, 118, 140, 81, 38,
               115, 101, 99, NA, 129, 72, 45, 110, 92, 104, 116, 138, 79, 40)
)
check_visits <- function(df) {
  problems <- character(0)
  bad <- sum(is.na(df$visitors) | df$visitors < 0)
  if (bad > 0) problems <- c(problems, paste(bad, "missing or negative counts"))
  if (any(diff(df$date) != 1)) problems <- c(problems, "dates have gaps")
  problems
}
clean_visits <- function(df) {
  df$visitors[!is.na(df$visitors) & df$visitors < 0] <- NA
  df$weekday <- factor(weekdays(df$date), levels = c("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"))
  df
}
clean <- clean_visits(visits)
report <- function(df) {
  per_day <- tapply(df$visitors, df$weekday, mean, na.rm = TRUE)
  weekend <- df$weekday %in% c("Saturday", "Sunday")
  c(
    paste0("Days: ", nrow(df), " (", sum(is.na(df$visitors)), " not counted)"),
    paste0("Busiest day: ", names(which.max(per_day)), " (", round(max(per_day, na.rm = TRUE), 2), " a day)"),
    paste0("Weekdays: ", round(mean(df$visitors[!weekend], na.rm = TRUE), 1), " a day, weekends: ", round(mean(df$visitors[weekend], na.rm = TRUE), 1), " a day")
  )
}
cat(report(clean), sep = "\n")
cat("\n")

